def findRelativeRanks(score):
    # Step 1: Copy the scores
    sorted_scores = score[:]

    # Step 2: Sort the scores in descending order using bubble sort
    n = len(sorted_scores)
    for i in range(n):
        for j in range(0, n-i-1):
            if sorted_scores[j] < sorted_scores[j+1]:
                # Swap if the element found is less than the next element
                sorted_scores[j], sorted_scores[j+1] = sorted_scores[j+1], sorted_scores[j]

    # Step 3: Map ranks to scores
    rank_dict = {}
    for i in range(n):
        if i == 0:
            rank_dict[sorted_scores[i]] = "Gold Medal"
        elif i == 1:
            rank_dict[sorted_scores[i]] = "Silver Medal"
        elif i == 2:
            rank_dict[sorted_scores[i]] = "Bronze Medal"
        else:
            rank_dict[sorted_scores[i]] = str(i + 1)

    # Step 4: Assign ranks to the original scores
    answer = []
    for s in score:
        answer.append(rank_dict[s])

    return answer

# Example usage:
print(findRelativeRanks([5, 4, 3, 2, 1]))  # Output: ["Gold Medal", "Silver Medal", "Bronze Medal", "4", "5"]
print(findRelativeRanks([10, 3, 8, 9, 4]))  # Output: ["Gold Medal", "5", "Bronze Medal", "Silver Medal", "4"]

