def deleteNodes(head, m, n):
    current = head
    prev = None

    while current:
        # Keep m nodes
        for _ in range(m):
            if not current:
                break
            prev = current
            current = current.next

        # Remove n nodes
        for _ in range(n):
            if not current:
                break
            current = current.next

        # Link the last kept node to the current node
        if prev:
            prev.next = current

    return head

