def reverseListIterative(head):
    prev = None
    current = head
    while current:
        next_node = current.next  # Store next node
        current.next = prev       # Reverse current node's pointer
        prev = current            # Move pointers one position ahead
        current = next_node
    return prev  # New head of the reversed list

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            self.parent[rootX] = rootY

def equationsPossible(equations):
    # Step 1: Initialize Union-Find structure for 26 letters
    uf = UnionFind(26)

    # Step 2: Process all "==" equations
    for eq in equations:
        if eq[1] == '=':
            uf.union(ord(eq[0]) - ord('a'), ord(eq[3]) - ord('a'))

    # Step 3: Check all "!=" equations
    for eq in equations:
        if eq[1] == '!':
            if uf.find(ord(eq[0]) - ord('a')) == uf.find(ord(eq[3]) - ord('a')):
                return False

    # Step 4: All equations are satisfied
    return True

# Example usage:
print(equationsPossible(["a==b", "b!=a"]))  # Output: False
print(equationsPossible(["b==a", "a==b"]))  # Output: True
print(equationsPossible(["a==b", "b==c", "a==c"]))  # Output: True
print(equationsPossible(["a==b", "b!=c", "c==a"]))  # Output: False
print(equationsPossible(["c==c", "b==d", "x!=z"]))  # Output: True

