def minRemoveToMakeValid(s):
    # First pass: left to right
    result = []
    open_count = 0

    for char in s:
        if char == '(':
            open_count += 1
            result.append(char)
        elif char == ')':
            if open_count > 0:
                open_count -= 1
                result.append(char)
        else:
            result.append(char)

    # Second pass: right to left
    close_count = 0
    final_result = []

    for char in reversed(result):
        if char == ')':
            close_count += 1
            final_result.append(char)
        elif char == '(':
            if close_count > 0:
                close_count -= 1
                final_result.append(char)
        else:
            final_result.append(char)

    # The final result is in reverse order, so reverse it back
    final_result.reverse()

    return ''.join(final_result)

# Example usage:
print(minRemoveToMakeValid("lee(t(c)o)de)"))  # Output: "lee(t(c)o)de"
print(minRemoveToMakeValid("a)b(c)d"))        # Output: "ab(c)d"
print(minRemoveToMakeValid("))(("))           # Output: ""
print(minRemoveToMakeValid("(a(b(c)d)"))      # Output: "a(b(c)d)"

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1
            return True
        return False

def maxNumEdgesToRemove(n, edges):
    alice_uf = UnionFind(n + 1)
    bob_uf = UnionFind(n + 1)

    # Count of edges used
    edges_used = 0

    # Process type 3 edges
    for t, u, v in edges:
        if t == 3:
            if alice_uf.union(u, v):
                bob_uf.union(u, v)
                edges_used += 1

    # Process type 1 edges for Alice
    for t, u, v in edges:
        if t == 1:
            if alice_uf.union(u, v):
                edges_used += 1

    # Process type 2 edges for Bob
    for t, u, v in edges:
        if t == 2:
            if bob_uf.union(u, v):
                edges_used += 1

    # Check if both Alice and Bob can traverse all nodes
    if len({alice_uf.find(i) for i in range(1, n + 1)}) != 1 or len({bob_uf.find(i) for i in range(1, n + 1)}) != 1:
        return -1

    return len(edges) - edges_used

# Example usage:
print(maxNumEdgesToRemove(4, [[3,1,2],[3,2,3],[1,1,3],[1,2,4],[1,1,2],[2,3,4]]))  # Output: 2
print(maxNumEdgesToRemove(4, [[3,1,2],[3,2,3],[1,1,4],[2,1,4]]))  # Output: 0
print(maxNumEdgesToRemove(4, [[3,2,3],[1,1,2],[2,3,4]]))  # Output: -1

def min_operations_to_subsequence(target, arr):
    # Step 1: Create a mapping from target elements to their indices
    target_map = {}
    for i, num in enumerate(target):
        target_map[num] = i

    # Step 2: Transform arr using the mapping
    transformed_arr = []
    for num in arr:
        if num in target_map:
            transformed_arr.append(target_map[num])

    # Step 3: Find the Longest Increasing Subsequence (LIS) in the transformed array
    def find_lis(sequence):
        if not sequence:
            return 0

        # Initialize the lis array with 1s
        lis = [1] * len(sequence)

        # Fill lis array
        for i in range(1, len(sequence)):
            for j in range(i):
                if sequence[i] > sequence[j]:
                    lis[i] = max(lis[i], lis[j] + 1)

        # Return the maximum value in lis array
        return max(lis)

    lis_length = find_lis(transformed_arr)

    # Step 4: Calculate the minimum number of insertions
    return len(target) - lis_length

# Example usage:
target1 = [5, 1, 3]
arr1 = [9, 4, 2, 3, 4]
print(min_operations_to_subsequence(target1, arr1))  # Output: 2

target2 = [6, 4, 8, 1, 3, 2]
arr2 = [4, 7, 6, 2, 3, 8, 6, 1]
print(min_operations_to_subsequence(target2, arr2))  # Output: 3
